param([Parameter(Mandatory=$true)][string]$ArchiveUrl,[Parameter(Mandatory=$true)][string]$ArchiveSha256,[Parameter(Mandatory=$true)][long]$ArchiveBytes,[string]$Components='ae,server',[string]$Destination=(Join-Path $env:LOCALAPPDATA 'VarnaMotionStudio\Connect58Package'))
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'Invoke-Checked58.ps1')
if($ArchiveUrl -notmatch '^https://github.com/abolfazlghashghaei/Varna-Motions-Studio/archive/[a-f0-9]{40}\.zip$' -or $ArchiveSha256 -notmatch '^[a-f0-9]{64}$'){throw 'Invalid release metadata'}
$choices=@($Components.Split(',')|Where-Object {$_});foreach($c in $choices){if($c -notin @('ae','engine','premiere','resolve','server')){throw 'Unknown component'}}
if('engine' -in $choices -and 'ae' -notin $choices){throw 'Local AE engine requires the AE panel component'}
$cache=Join-Path $env:LOCALAPPDATA 'VarnaMotionStudio\Installer58';New-Item -ItemType Directory $cache -Force|Out-Null
$zip=Join-Path $cache ($ArchiveSha256+'.zip')
function ValidArchive {return (Test-Path -LiteralPath $zip) -and (Get-Item -LiteralPath $zip).Length -eq $ArchiveBytes -and (Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash -eq $ArchiveSha256}
if(!(ValidArchive)){$download=$zip+'.download';try{[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12;(New-Object Net.WebClient).DownloadFile($ArchiveUrl,$download);if((Get-Item -LiteralPath $download).Length -ne $ArchiveBytes -or (Get-FileHash -LiteralPath $download -Algorithm SHA256).Hash -ne $ArchiveSha256){throw 'Release download checksum failed'};Move-Item -LiteralPath $download -Destination $zip -Force}finally{Remove-Item -LiteralPath $download -Force -ErrorAction SilentlyContinue}}
$stage=Join-Path $env:TEMP ('V58-'+[guid]::NewGuid().ToString('N').Substring(0,8));New-Item -ItemType Directory $stage|Out-Null
try{Expand-Archive -LiteralPath $zip -DestinationPath $stage;$root=@(Get-ChildItem -LiteralPath $stage -Directory);if($root.Count -ne 1){throw 'Invalid archive layout'};$source=$root[0].FullName
foreach($required in @('Varna_Motion_Studio\INSTALL_WINDOWS.ps1','Varna_Motion_Studio\integrations\INSTALL_CROSS_HOST_WINDOWS.ps1','connect58\server.cjs')){if(!(Test-Path -LiteralPath (Join-Path $source $required))){throw ('Missing release component: '+$required)}}
$backup=$Destination+'.backup-'+[guid]::NewGuid().ToString('N');if(Test-Path -LiteralPath $Destination){Move-Item -LiteralPath $Destination -Destination $backup};New-Item -ItemType Directory (Split-Path $Destination -Parent) -Force|Out-Null;try{Move-Item -LiteralPath $source -Destination $Destination}catch{if(Test-Path -LiteralPath $backup){Move-Item -LiteralPath $backup -Destination $Destination};throw}
$payload=Join-Path $Destination 'Varna_Motion_Studio'
# All hosts and the personal server reuse one verified application runtime.
& (Join-Path $payload 'integrations\INSTALL_CROSS_HOST_WINDOWS.ps1') -HostApp Editor
if('ae' -in $choices){Invoke-Checked58 (Join-Path $Destination 'PREPARE_GITHUB_DOWNLOAD.ps1');$level=if('engine' -in $choices){'Max'}else{'Studio'};$requireEngine='engine' -in $choices;Invoke-Checked58 (Join-Path $payload 'INSTALL_WINDOWS.ps1') @{Level=$level;RequireHealthyEngine=$requireEngine}}
foreach($hostName in @('Premiere','Resolve')){if($hostName.ToLower() -in $choices){& (Join-Path $payload 'integrations\INSTALL_CROSS_HOST_WINDOWS.ps1') -HostApp $hostName}}
if('server' -in $choices){$serverRoot=Join-Path $env:LOCALAPPDATA 'VarnaMotionStudio\Connect58';New-Item -ItemType Directory $serverRoot -Force|Out-Null;$config=Join-Path $serverRoot 'server.json';if(!(Test-Path -LiteralPath $config)){$bytes=New-Object byte[] 32;$rng=[Security.Cryptography.RandomNumberGenerator]::Create();try{$rng.GetBytes($bytes)}finally{$rng.Dispose()};$token=([BitConverter]::ToString($bytes)).Replace('-','').ToLower();$ffmpeg=Join-Path $payload 'assets\vendor\Railcut\Railcut\bin\win\ffmpeg.exe';$manifest=Get-Content -LiteralPath (Join-Path $payload 'PACKAGE_MANIFEST.json') -Raw|ConvertFrom-Json;$entry=@($manifest.files|Where-Object {$_.path -eq 'assets/vendor/Railcut/Railcut/bin/win/ffmpeg.exe'})[0];if((Get-FileHash -LiteralPath $ffmpeg -Algorithm SHA256).Hash -ne $entry.sha256){throw 'Bundled FFmpeg checksum failed'};@{token=$token;bind='127.0.0.1';port=8798;ffmpeg=$ffmpeg;whisper='';model=''}|ConvertTo-Json|Set-Content -LiteralPath $config -Encoding UTF8}
$spec=Get-Content -LiteralPath (Join-Path $payload 'integrations\resolve\runtime54.json') -Raw|ConvertFrom-Json;$exe=Join-Path $env:LOCALAPPDATA ('VarnaMotionStudio\Runtime54\'+$spec.version+'\electron.exe');$launch=Join-Path $serverRoot 'START_SERVER.cmd';[IO.File]::WriteAllText($launch,"@echo off`r`nset ELECTRON_RUN_AS_NODE=1`r`n`"$exe`" `"$(Join-Path $Destination 'connect58\server.cjs')`"`r`npause`r`n")
$shell=New-Object -ComObject WScript.Shell;$link=$shell.CreateShortcut((Join-Path ([Environment]::GetFolderPath('Desktop')) 'Personal Processing Server.lnk'));$link.TargetPath=$launch;$link.Save();$internet=$shell.CreateShortcut((Join-Path ([Environment]::GetFolderPath('Desktop')) 'Personal Server - Internet.lnk'));$internet.TargetPath='powershell.exe';$internet.Arguments='-NoProfile -ExecutionPolicy Bypass -File "'+(Join-Path $Destination 'connect58\Start-Internet58.ps1')+'"';$internet.Save();Write-Host ('Server settings and pairing key: '+$config)}
Write-Host 'Installation completed. Restart the selected hosts. Personal processing requires the PC and server to remain running.'
}finally{Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue}
